const removedCourse=i=>!!(key&&state?.courses?.[i]?.removed);
function issueSummary(issues){const nameOf=s=>{const m=String(s).match(/^(.+?)(?:\s第\d+回)?：/);return m?m[1]:String(s)},reasonOf=s=>{const i=String(s).indexOf('：');return i<0?String(s):String(s).slice(i+1)};const undated=[...new Set(issues.filter(s=>/：授業日未設定/.test(s)).map(nameOf))],groups=new Map();for(const s of issues.filter(s=>!/：授業日未設定/.test(s))){const r=reasonOf(s);groups.set(r,[...new Set([...(groups.get(r)||[]),nameOf(s)])])}return {undated,other:[...groups].map(([reason,names])=>({reason,names}))}}
const dev=()=>state?.os==='win32'?'PC':'Mac';
let state=emptyState(),view='home',filter=DEFAULT_FILTER,query='',selectedCourse=null,lastFocus=null,dialogDone=null,key=localStorage.getItem('coursecue-owner')||'';
// 画面の状態：Mac の記録を読めたか（loaded）、接続できない理由（offline）、処理中のボタン（busy）、ドロワーの未保存（dirty）、メニュー・ディレクトリの開閉
let loaded=!key,offline='',dirty=false,drawerRoute='',pendingDrawer='',restoring=false,menuOpen=false,dirOpen=false;const busy={};
const ownerCourses=[...courses];let guestData;try{guestData=JSON.parse(localStorage.getItem('coursecue-personal')||'null')}catch{}if(!key){courses=guestData?.courses||[];state=guestData?.state||emptyState();}function savePersonal(){localStorage.setItem('coursecue-personal',JSON.stringify({courses,state}));}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DAY=86400000,HOUR=3600000;const dueTime=t=>t.dueAt?new Date(t.dueAt).getTime():null;
const when=s=>s?new Date(s).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo',month:'numeric',day:'numeric',weekday:'short',hour:'2-digit',minute:'2-digit'}):'未確認';
const needs=t=>['wait','code','unknown','answered'].includes(t.status);const pending=t=>t.status!=='done';
const overdue=t=>pending(t)&&!!t.dueAt&&dueTime(t)<=Date.now();const soon=t=>pending(t)&&!!t.dueAt&&dueTime(t)>Date.now()&&dueTime(t)-Date.now()<=3*DAY;
function remaining(t){const ms=dueTime(t)-Date.now(),a=Math.abs(ms),span=a>=DAY?Math.floor(a/DAY)+'日':a>=HOUR?Math.floor(a/HOUR)+'時間':Math.max(1,Math.floor(a/60000))+'分';return ms<=0?'期限切れ · '+span+'超過':'あと'+span}
// 連携時は manabo から未取得、個人用では本人が未入力なので言い方を変える
const noDue=()=>key?'締切未確認':'締切未設定';
function deadline(t){if(!t.dueAt)return `<span class="deadline">${noDue()}</span>`;if(!pending(t))return `<span class="deadline">締切 ${when(t.dueAt)}</span>`;const level=overdue(t)?'overdue':dueTime(t)-Date.now()<=DAY?'urgent':soon(t)?'soon':'';return `<span class="deadline ${level}">締切 ${when(t.dueAt)}<small>${remaining(t)}</small></span>`}
const localInput=s=>{if(!s)return '';const d=new Date(s);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)};
const round=t=>t.round?'第'+t.round+'回':key?'回数未確認':'回数未設定';
async function api(path,method='GET',data){const r=await fetch(API+path,{method,headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});if(r.status===401)throw Error(dev()+' から接続してください');if(!r.ok)throw Error('接続できません');return r.json()}
function toast(s){const e=document.getElementById('toast');e.textContent=s;e.style.display='block';e.onclick=()=>{e.style.display='none'};clearTimeout(window.tt);window.tt=setTimeout(()=>e.style.display='none',5000)}
// 「3時間前」など。ヘッダーの同期時刻に添える
function ago(s){if(!s)return '';const m=Math.round((Date.now()-new Date(s))/60000);return m<1?'たった今':m<60?`${m}分前`:m<1440?`${Math.floor(m/60)}時間前`:`${Math.floor(m/1440)}日前`}
// 履歴（戻る・進む）：#v=画面&c=授業&f=絞り込み&d=ドロワー
const hasHistory=typeof history!=='undefined'&&typeof history.pushState==='function';
function hashOf(){const p=new URLSearchParams();if(view!=='home')p.set('v',view);if(selectedCourse!==null)p.set('c',selectedCourse);if(filter!==DEFAULT_FILTER)p.set('f',filter);if(drawerRoute)p.set('d',drawerRoute);const s=p.toString();return s?'#'+s:location.pathname+(location.search||'')}
function pushRoute(replace=false){if(!hasHistory)return;const data={saboro:true,d:drawerRoute};try{replace?history.replaceState(data,'',hashOf()):history.pushState(data,'',hashOf())}catch{}}
function readRoute(){const p=new URLSearchParams((location.hash||'').slice(1));const v=p.get('v');view=v&&views[v]?v:'home';const c=p.get('c');selectedCourse=c!==null&&courses[+c]!==undefined?+c:null;if(selectedCourse!==null)view='courses';filter=filters.includes(p.get('f'))?p.get('f'):DEFAULT_FILTER;return p.get('d')||''}
function go(v,c=null,f=DEFAULT_FILTER){view=v;selectedCourse=c;filter=f;menuOpen=false;dirOpen=false;pushRoute();render();if(typeof scrollTo==='function')scrollTo(0,0)}
function openRoute(d){const [kind,arg='']=d.split(':');if(kind==='task')detail(arg);else if(kind==='new')addTaskDrawer();else if(kind==='session'&&typeof openSession==='function'){const [i,r]=arg.split('.').map(Number);if(courses[i]!==undefined&&r)openSession(i,r)}else if(kind==='course'&&typeof openCourseConfig==='function'&&courses[+arg]!==undefined)openCourseConfig(+arg);else if(kind==='att'&&typeof openAttendance==='function'&&courses[+arg]!==undefined)openAttendance(+arg)}
function restoreDrawer(){if(!pendingDrawer||!loaded)return;const d=pendingDrawer;pendingDrawer='';restoring=true;try{openRoute(d)}finally{restoring=false}}
// 処理中のボタン：再描画しても「同期中…」などの表示と無効化を保つ
function setBusy(id,label){if(label)busy[id]=label;else delete busy[id];applyBusy()}
function applyBusy(){for(const [id,label] of Object.entries(busy)){const b=document.getElementById(id);if(b){b.disabled=true;b.textContent=label}}if(key&&state.running&&!busy.sync){const b=document.getElementById('sync');if(b){b.disabled=true;b.textContent=state.running==='sync'?'同期中…':dev()+' が処理中…'}}}
async function load(){if(document.activeElement?.matches?.('input,textarea,select'))return;if(!key){render();return}try{state=await api('/api/state');adoptCourses();const first=!loaded;loaded=true;if(offline){offline='';toast('接続を回復しました')}if(typeof reapplyPending==='function')reapplyPending();render();if(first)restoreDrawer()}catch(e){if(offline!==e.message)toast(e.message);offline=e.message;render()}}
async function job(kind,task=null,payload={},buttonFor=null){if(!key){toast('manabo連携が必要です');return}try{const queued=await api('/api/jobs','POST',{kind,task,payload});toast(payload.pickDownloadDir?dev()+' にフォルダの選択画面を出します':kind==='sync'?'同期を開始します':kind==='generate'?'自動回答を開始します':kind==='supplement'||kind==='timetable'?'保存しました':kind==='link'?'対応づけを予約しました。次の同期で締切・提出状況を確認します':'処理を予約しました');if(['generate','sync','settings','attendance'].includes(kind)){const buttonId=buttonFor||(kind==='sync'?'sync':kind==='settings'?'savesettings':'generate');setBusy(buttonId,kind==='sync'?'同期開始待ち…':payload.pickDownloadDir?dev()+' の応答待ち…':kind==='settings'?dev()+' に反映中…':'開始待ち…');const poll=setInterval(async()=>{try{const jobs=await api('/api/jobs');const current=jobs.find(j=>j.id===queued.id);if(!current)return;setBusy(buttonId,payload.pickDownloadDir?(current.status==='running'?dev()+' で選択してください…':state.running?dev()+' が別の処理中（終わると画面が出ます）…':dev()+' の応答待ち…'):kind==='settings'?dev()+' に反映中…':current.status==='running'?(kind==='sync'?'同期中…':kind==='attendance'?'提出中…':'回答中…'):'開始待ち…');if(['done','waiting','failed'].includes(current.status)){clearInterval(poll);setBusy(buttonId,'');await load();if(task&&!dirty&&document.getElementById('overlay').classList.contains('open'))detail(task);const result=typeof current.result==='string'?JSON.parse(current.result):current.result;toast(kind==='attendance'&&result?.taskStatus==='done'?'出席コードを入れて提出しました':kind==='sync'&&current.status==='done'?'同期しました':kind==='settings'&&current.status==='done'?(payload.pickDownloadDir||payload.downloadDir!==undefined?(result?.message||dev()+' が新しい版ではないため変更できませんでした'):'設定を保存しました'):briefError(result?.message||'処理を確認してください'));}}catch{clearInterval(poll);setBusy(buttonId,'');toast('処理状況を取得できません');}},2000);}await load()}catch(e){toast(e.message)}}
// confirm() の代わりに使う確認ダイアログ
function ask(message,ok='OK',danger=false){return new Promise(resolve=>{const d=document.getElementById('dialog'),prev=document.activeElement;d.innerHTML=`<div class="modal" role="alertdialog" aria-modal="true" aria-labelledby="dialog-title" aria-describedby="dialog-text"><div class="modal-header" id="dialog-title">確認</div><p class="modal-body" id="dialog-text">${esc(message)}</p><div class="modal-footer"><button class="btn" id="dialog-cancel">キャンセル</button><button class="btn ${danger?'btn-danger':'btn-primary'}" id="dialog-ok">${esc(ok)}</button></div></div>`;d.classList.add('open');const done=v=>{d.classList.remove('open');d.innerHTML='';dialogDone=null;prev?.focus?.();resolve(v)};dialogDone=done;document.getElementById('dialog-ok').onclick=()=>done(true);document.getElementById('dialog-cancel').onclick=()=>done(false);d.onclick=e=>{if(e.target===d)done(false)};document.getElementById('dialog-cancel').focus()})}
// ドロワー。route を渡すと履歴に積み、戻るで閉じられる。別のドロワーに置き換わるときは履歴を増やさない
function openDrawer(title,body,focusId,route=''){const o=document.getElementById('overlay'),was=o.classList.contains('open');if(!was)lastFocus=document.activeElement;const d=document.getElementById('drawer');d.innerHTML=`<div class="drawerhead"><h2 id="drawer-title">${esc(title)}</h2><button class="close" id="close" aria-label="閉じる">${ic('close')}</button></div><div class="drawerbody">${body}</div>`;dirty=false;d.oninput=()=>{dirty=true};o.classList.add('open');document.body.style.overflow='hidden';document.getElementById('close').onclick=()=>close();if(route){const changed=route!==drawerRoute;drawerRoute=route;if(changed&&!restoring)pushRoute(was)}applyBusy();document.getElementById(focusId||'close').focus()}
function closeNow(){const o=document.getElementById('overlay');dirty=false;drawerRoute='';if(!o.classList.contains('open'))return;o.classList.remove('open');document.body.style.overflow='';lastFocus?.focus?.()}
async function close(force=false){const o=document.getElementById('overlay');if(!o.classList.contains('open'))return;if(!force&&dirty&&!await ask('保存していない変更があります。閉じますか？','閉じる',true))return;const pushed=hasHistory&&history.state?.d;closeNow();if(pushed)history.back();else pushRoute(true)}
const panel=(title,body,{mark=true,center=false,tools='',flush=false,id=''}={})=>`<section class="panel"${id?` id="${id}"`:''}><h2 class="panel-heading${center?' center':''}">${mark?'<span class="mark" aria-hidden="true"></span>':''}${title}${tools?`<span class="tools">${tools}</span>`:''}</h2><div class="panel-body${flush?' flush':''}">${body}</div></section>`;
function row(t){const [label,cl]=statuses[t.status]||['未確認','ready'];return `<li><button class="task" data-task="${esc(t.id)}"><span class="task-main"><span class="task-title">${esc(t.title)}</span><span class="meta">${esc(courses[t.course]??'授業未設定')} · ${round(t)} · ${esc(t.type||'課題')}</span>${needs(t)&&t.action?`<span class="rowaction">${esc(t.action)}</span>`:''}</span><span class="right"><span class="label ${cl}">${label}</span>${deadline(t)}</span></button></li>`}
const inFilter=(t,f)=>f==='all'||f==='pending'&&pending(t)||f==='done'&&!pending(t)||f==='soon'&&soon(t)||f==='overdue'&&overdue(t);
function matched(t,f=filter){const q=query.trim().toLowerCase();return(!q||((courses[t.course]||'')+t.title).toLowerCase().includes(q))&&(selectedCourse===null||selectedCourse===t.course)&&inFilter(t,f)}
const byDue=(a,b)=>(pending(b)-pending(a))||((dueTime(a)??Infinity)-(dueTime(b)??Infinity));
// タブには絞り込み前の件数を添える
function list(rows,tabs=true,empty='課題はありません'){const shown=rows.filter(t=>matched(t)).sort(byDue),all=rows.filter(t=>matched(t,'all')).length;return `${tabs?`<div class="tabs">${[['pending','未提出'],['overdue','期限切れ'],['soon','3日以内'],['done','提出済み'],['all','すべて']].map(([v,l])=>`<button class="tab ${v===filter?'active':''}" data-filter="${v}" aria-pressed="${v===filter}">${l}<span class="count">${rows.filter(t=>matched(t,v)).length}</span></button>`).join('')}</div>`:''}${shown.length?`<ul class="tasklist">${shown.map(row).join('')}</ul>`:`<p class="empty">${query?'検索に一致する課題はありません':tabs&&filter!=='all'&&all?`この絞り込みに該当する課題はありません。<button class="linklike" data-filter="all">すべて（${all}件）を見る</button>`:empty}</p>`}`}
// 授業ページの先頭：曜日・教室・形式・次回・出席のまとめ（時間割の関数がある場合）
function courseHeader(i){if(typeof courseConfig!=='function')return '';const cfg=courseConfig(i),s=typeof attendanceSummary==='function'?attendanceSummary(i):null,dates=typeof courseDates==='function'?courseDates(i):{},today=typeof todayISO==='function'?todayISO():'',next=Object.entries(dates).find(([,d])=>d>=today);const unset='<span class="muted">未設定</span>';return panel('授業の情報',`<table class="table-default"><tr><th>曜日・時限</th><td>${cfg.weekday?`${esc(cfg.weekday)}曜${cfg.period?` ${cfg.period}限`:''}`:unset}</td></tr><tr><th>教室</th><td>${esc(cfg.room)||unset}</td></tr><tr><th>授業形式</th><td>${(typeof modeLabel==='function'&&modeLabel(cfg.mode))||unset}${cfg.modeFrom?` <span class="muted">（${cfg.modeFrom==='CUBICS'?'CUBICSから推定':'資料'}）</span>`:''}</td></tr><tr><th>次回</th><td>${next?`第${next[0]}回 ${typeof dayLabel==='function'?dayLabel(next[1]):next[1]}${next[1]===today?' <span class="label draft">今日</span>':''}`:'<span class="muted">予定なし</span>'}</td></tr>${s?`<tr><th>出席</th><td>出席 ${s.出席}・遅刻 ${s.遅刻}・欠席 ${s.欠席}・公欠 ${s.公欠}${cfg.limit!=null?`（欠席の上限 ${cfg.limit}回）`:''}${s.未記録?` <span class="attn">未記録 ${s.未記録}</span>`:''}</td></tr>`:''}</table><div class="actions"><button class="btn btn-sm" data-coursecfg="${i}">授業の設定</button><button class="btn btn-sm" data-attendance="${i}">出席を記録</button><button class="btn btn-sm" data-view="timetable">時間割へ</button>${key&&state.features?.includes('removecourse')?`<button class="btn btn-sm" id="removecourse-${i}" data-removecourse="${i}">この授業を削除</button>`:''}</div>`)}
// 左のディレクトリ。スマホでは manabo と同じくボタンで開閉する
function directory(){const total=state.tasks.filter(pending).length;return `<button class="menu-collapse" id="dirtoggle" aria-expanded="${dirOpen}" aria-controls="dirpanel">ディレクトリ${total?`<span class="badge">${total}<span class="sr-only">件未提出</span></span>`:''}</button>`+panel('ディレクトリ',`<button class="topdir ${view==='courses'&&selectedCourse===null?'selected':''}" data-view="courses">授業一覧</button><ul class="dirlist">${courses.map((c,i)=>{if(removedCourse(i))return '';const n=state.tasks.filter(t=>t.course===i&&pending(t)).length;return `<li><button data-course="${i}" class="${selectedCourse===i?'selected':''}"${selectedCourse===i?' aria-current="page"':''}><img class="folder-icon" src="/folder-icon.png" alt="" width="16" height="12">${esc(c)}${n?`<span class="badge">${n}<span class="sr-only">件未提出</span></span>`:''}</button></li>`}).join('')}</ul>`,{mark:false,center:true,id:'dirpanel'})}
function courseTable(){const rows=courses.map((c,i)=>({c,i})).filter(({i})=>!removedCourse(i)).filter(({c})=>!query||c.toLowerCase().includes(query.trim().toLowerCase()));return rows.length?`<table class="table-default"><thead><tr><th scope="col">授業名</th><th scope="col" class="num">課題</th><th scope="col" class="num">未提出</th></tr></thead><tbody>${rows.map(({c,i})=>{const ts=state.tasks.filter(t=>t.course===i);return `<tr><td><button class="linklike" data-course="${i}">${esc(c)}</button></td><td class="num">${ts.length}</td><td class="num">${ts.filter(pending).length}</td></tr>`}).join('')}</tbody></table>`:'<p class="empty">授業がありません</p>'}
