const importer=document.getElementById('importpersonal');if(importer)importer.onchange=async()=>{try{const d=JSON.parse(await importer.files[0].text());if(d.version!==1||!Array.isArray(d.courses)||!d.courses.every(c=>typeof c==='string')||!Array.isArray(d.state?.tasks)||!Array.isArray(d.state?.materials)||d.state.tasks.some(t=>typeof t.id!=='string'||typeof t.title!=='string'||!Number.isInteger(t.course)||t.course<0||t.course>=d.courses.length))throw Error();if(!await ask('このブラウザのデータをバックアップの内容で置き換えますか？現在のデータは消えます。','置き換える',true))return;courses=d.courses;state=d.state;selectedCourse=null;savePersonal();render();toast('読み込みました')}catch{toast('バックアップを確認してください')}finally{importer.value=''}};
document.querySelectorAll('[data-rename]').forEach(e=>e.onclick=()=>{const i=+e.dataset.rename,name=document.getElementById('coursename-'+i).value.trim();if(!name){toast('授業名を入力してください');return}if(courses.some((c,j)=>c===name&&j!==i)){toast('登録済みの授業です');return}const old=courses[i];for(const k of ['timetable','sessions'])if(state[k]?.[old]){state[k]={...state[k],[name]:state[k][old]};delete state[k][old]}courses[i]=name;savePersonal();render();toast('授業名を変更しました')});
document.querySelectorAll('[data-removecourse]').forEach(e=>e.onclick=async()=>{const i=+e.dataset.removecourse,name=courses[i],count=state.tasks.filter(t=>t.course===i).length;if(!await ask(`「${name}」を削除しますか？今後この授業の課題・資料は manabo から集めません${count?`（課題 ${count} 件も一覧から外します）`:''}。ダウンロード済みの資料はフォルダに残ります。授業一覧の「削除した授業」から元に戻せます。`,'削除',true))return;await job('settings',null,{removeCourse:name},e.id)});
document.querySelectorAll('[data-restorecourse]').forEach(e=>e.onclick=()=>job('settings',null,{restoreCourse:courses[+e.dataset.restorecourse]},e.id));
document.querySelectorAll('[data-delcourse]').forEach(e=>e.onclick=async()=>{const i=+e.dataset.delcourse,count=state.tasks.filter(t=>t.course===i).length;if(!await ask(`「${courses[i]}」${count?`と課題${count}件`:''}を削除しますか？元に戻せません。`,'削除',true))return;state.tasks=state.tasks.filter(t=>t.course!==i).map(t=>t.course>i?{...t,course:t.course-1}:t);for(const k of ['timetable','sessions'])if(state[k])delete state[k][courses[i]];courses.splice(i,1);selectedCourse=null;savePersonal();render();toast('授業を削除しました')});
bind('sync',()=>job('sync'));bind('verifylogin',()=>job('verify'));
bind('savecredentials',async()=>{const username=document.getElementById('manabo-id').value.trim(),password=document.getElementById('manabo-password').value;if(!username||!password){toast('ID・パスワードを入力してください');return}if(!state.credentialPublicKey){toast(dev()+' の接続を確認してください');return}try{const {encryptCredentials}=await import('./credentials.js');const payload=await encryptCredentials(state.credentialPublicKey,username,password);await api('/api/jobs','POST',{kind:'credentials',payload});document.getElementById('manabo-password').value='';toast('保存を予約しました。'+dev()+' で処理します。')}catch{toast('保存できませんでした')}});
bind('logout',async()=>{if(!await ask('この端末と'+dev()+' の接続を解除しますか？再接続には'+dev()+' の設定画面が必要です。','解除する',true))return;key='';localStorage.removeItem('coursecue-owner');courses=guestData?.courses||[];state=guestData?.state||emptyState();loaded=true;offline='';view='home';selectedCourse=null;pushRoute(true);render()});
// 実行時刻・自動生成・授業日を一度に保存する（ダウンロード先は別：押した時点で反映）
bind('savesettings',async()=>{const schedules=await schedulesFromInputs();job('settings',null,{time:document.getElementById('time').value,autoGenerate:document.getElementById('autogen').checked,autoSubmitQuiz:false,schedules})});
bind('pickdir',()=>job('settings',null,{pickDownloadDir:true},'pickdir'));
